const reqs = $('Repos').all();
const res = $input.all();
const out = [];
for (let i = 0; i < res.length; i++) {
  const repo = reqs[i].json.repo;
  const bs = Array.isArray(res[i].json.body) ? res[i].json.body : [];
  const names = bs.map(function (b) { return b.name; });
  const pick = names.filter(function (n) { return /^(develop|dev|main|master)$/i.test(n) || /2580|austral|statdec|nat.?3092|su001|su580|rotate|instruction/i.test(n); });
  for (const n of pick) { out.push({ json: { repo: repo, branch: n, all_branches: names.length } }); }
  if (pick.length === 0) { out.push({ json: { repo: repo, branch: 'HEAD', status: res[i].json.statusCode, all_branches: names.length } }); }
}
return out;

const reqs = $('Commit Reqs').all();
const res = $input.all();
const seen = {};
const out = [];
for (let i = 0; i < res.length; i++) {
  const rq = reqs[i].json;
  const cs = Array.isArray(res[i].json.body) ? res[i].json.body : [];
  for (const c of cs) {
    const k = rq.repo + '@' + c.sha;
    if (seen[k]) { seen[k].branches.push(rq.branch); continue; }
    const o = { repo: rq.repo, sha: c.sha, branches: [rq.branch], message: (c.commit && c.commit.message || '').slice(0, 300), date: c.commit && c.commit.author && c.commit.author.date, author: c.commit && c.commit.author && c.commit.author.name, url: c.html_url };
    seen[k] = o;
    out.push({ json: o });
  }
}
if (out.length === 0) { out.push({ json: { repo: 'none', sha: 'none', branches: [], message: 'NO COMMITS', statuses: res.map(function (r) { return r.json.statusCode; }) } }); }
return out.slice(0, 150);

const TERMS = ['nat3092','statdec','su001','su580','nat-3092','statutory-declaration','disclaimerAto','disclaimerAustralianGovernment','disclaimerServicesAustralia','quickLinks','instruction','rotate','2580'];
const cs = $('Pick Commits').all();
const res = $input.all();
const commits = [];
const matches = [];
for (let i = 0; i < res.length; i++) {
  const c = cs[i] ? cs[i].json : {};
  const body = res[i].json.body || {};
  const files = Array.isArray(body.files) ? body.files : [];
  let hits = 0;
  for (const f of files) {
    const lines = (f.patch || '').split('\n');
    for (let j = 0; j < lines.length; j++) {
      const ln = lines[j];
      if (ln.charAt(0) !== '+' && ln.charAt(0) !== '-') { continue; }
      const low = ln.toLowerCase();
      let t = null;
      for (const x of TERMS) { if (low.indexOf(x.toLowerCase()) >= 0) { t = x; break; } }
      if (!t) { continue; }
      hits++;
      if (matches.length < 700) { matches.push({ sha: (c.sha || '').slice(0, 9), repo: c.repo, file: f.filename, term: t, line: ln.slice(0, 220) }); }
    }
  }
  commits.push({ repo: c.repo, sha: (c.sha || '').slice(0, 9), branches: c.branches, date: c.date, author: c.author, message: c.message, url: c.url, files: files.length, file_names: files.map(function (f) { return f.filename; }).slice(0, 40), hits: hits, status: res[i].json.statusCode });
}
const br = $('Commit Reqs').all().map(function (x) { return x.json; });
return [{ json: { branches_checked: br, commits: commits, matches: matches } }];
